package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.mulAndCheck to maximize branch and line coverage.
 */
public class MathUtils_mulAndCheck_TriageGen1Test {











    @Test
    public void testMulAndCheck_NegativePositive_Overflow() {
        // Negative overflow: a * b < Long.MIN_VALUE
        // Long.MIN_VALUE is -9223372036854775808
        try {
            // -1 * (Long.MIN_VALUE - 1) would overflow, but we use Long.MIN_VALUE
            // If a = -1, b = Long.MIN_VALUE, -1 * Long.MIN_VALUE is positive overflow? 
            // Wait, the code logic: if (a < 0) and (b > 0), check (Long.MIN_VALUE / b <= a)
            // If a = -1, b = Long.MAX_VALUE: Long.MIN_VALUE / Long.MAX_VALUE = -1. -1 <= -1 is true.
            // To trigger overflow: a = -2, b = Long.MAX_VALUE. Long.MIN_VALUE / Long.MAX_VALUE = -1. -1 <= -2 is false.
            MathUtils.mulAndCheck(-2L, Long.MAX_VALUE);
            fail("Should have thrown ArithmeticException");
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }








}

