package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.mulAndCheck to maximize branch and line coverage.
 */
public class MathUtils_mulAndCheck_TriageGen1Test {



















    @Test
    public void testMulAndCheck_BoundaryLongMin() {
        // a=-1, b=Long.MIN_VALUE
        // a < 0, b < 0 is not possible here as Long.MIN_VALUE is negative.
        // Wait, if a = -1, b = Long.MIN_VALUE. a > b is true. 
        // Symmetry calls mulAndCheck(Long.MIN_VALUE, -1).
        // In second call: a = Long.MIN_VALUE, b = -1.
        // a < 0 is true. b < 0 is true.
        // Check: a >= Long.MAX_VALUE / b => Long.MIN_VALUE >= Long.MAX_VALUE / -1
        // Long.MAX_VALUE / -1 is -Long.MAX_VALUE.
        // Long.MIN_VALUE is -9223372036854775808. -Long.MAX_VALUE is -9223372036854775807.
        // -9223372036854775808 >= -9223372036854775807 is FALSE.
        // So -1 * Long.MIN_VALUE should throw ArithmeticException.
        try {
            MathUtils.mulAndCheck(-1L, Long.MIN_VALUE);
            fail("Should have thrown ArithmeticException");
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }
}
